package com.tanidikvar.api.evaluation.repository;
import com.tanidikvar.api.evaluation.dto.*;import java.sql.*;import java.time.Instant;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;
@Repository public class EvaluationRepository{
 private final JdbcTemplate jdbc;public EvaluationRepository(JdbcTemplate jdbc){this.jdbc=jdbc;}
 private EvaluationResponse map(ResultSet r,int n)throws SQLException{return new EvaluationResponse(r.getObject("id",UUID.class),r.getObject("author_id",UUID.class),r.getString("author_name"),r.getObject("university_id",UUID.class),r.getObject("university_department_id",UUID.class),r.getInt("rating"),r.getString("body"),r.getTimestamp("created_at").toInstant(),r.getTimestamp("updated_at").toInstant(),r.getLong("version"));}
 private static final String SELECT="SELECT e.*,concat_ws(' ',p.first_name,p.last_name) author_name FROM evaluations e JOIN user_profiles p ON p.user_id=e.author_id AND p.deleted_at IS NULL ";
 public boolean context(UUID university,UUID program){return program==null?Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM universities WHERE id=? AND deleted_at IS NULL)",Boolean.class,university)):Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM university_departments WHERE id=? AND university_id=? AND deleted_at IS NULL)",Boolean.class,program,university));}
 public EvaluationResponse save(UUID author,EvaluationRequest request){UUID id=UUID.randomUUID();UUID saved=jdbc.queryForObject("INSERT INTO evaluations(id,author_id,university_id,university_department_id,rating,body) VALUES (?,?,?,?,?,?) ON CONFLICT(author_id,university_id,university_department_id) DO UPDATE SET rating=excluded.rating,body=excluded.body,deleted_at=NULL,updated_at=CURRENT_TIMESTAMP,version=evaluations.version+1 RETURNING id",UUID.class,id,author,request.universityId(),request.programId(),request.rating(),request.body()==null?null:request.body().strip());return find(saved);}
 public EvaluationResponse find(UUID id){return jdbc.query(SELECT+"WHERE e.id=? AND e.deleted_at IS NULL",this::map,id).stream().findFirst().orElseThrow();}
 public List<EvaluationResponse> list(UUID university,UUID program,int page,int size){return jdbc.query(SELECT+"WHERE e.university_id=? AND e.university_department_id IS NOT DISTINCT FROM ? AND e.deleted_at IS NULL ORDER BY e.created_at DESC,e.id LIMIT ? OFFSET ?",this::map,university,program,size,page*size);}
 public long count(UUID university,UUID program){return jdbc.queryForObject("SELECT count(*) FROM evaluations WHERE university_id=? AND university_department_id IS NOT DISTINCT FROM ? AND deleted_at IS NULL",Long.class,university,program);}
 public EvaluationSummaryResponse summary(UUID university,UUID program){return jdbc.queryForObject("SELECT coalesce(round(avg(rating),2),0) average,count(*) total FROM evaluations WHERE university_id=? AND university_department_id IS NOT DISTINCT FROM ? AND deleted_at IS NULL",(r,n)->new EvaluationSummaryResponse(r.getDouble("average"),r.getLong("total")),university,program);}
}
